3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
8	
9	/**
10	 * Rejects a create request whose last name and address both match an existing owner's, so two owners
11	 * cannot share a household by accident. Last name is compared case-insensitively with collapsed
12	 * whitespace; address is compared in its normalized form (see {@link AddressNormalizer}). Runs
13	 * before {@link BuildOwner}; a match is a 409 via {@link DuplicateHouseholdException}. A request that
14	 * explicitly sets {@code sharesHousehold} true opts out of this check and is allowed.
15	 */
16	public class EnsureUniqueHousehold {
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws DuplicateHouseholdException {
20	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
21	            return;
22	        }
23	        String lastName = normalize(request.getLastName());
24	        String address = AddressNormalizer.normalize(request.getAddress());
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (normalize(existing.getLastName()).equals(lastName)
27	                    && AddressNormalizer.normalize(existing.getAddress()).equals(address)) {
28	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
29	            }
30	        }
31	    }
32	
33	    private static String normalize(String value) {
34	        if (value == null) {
35	            return "";
36	        }
37	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
38	    }
39	}
