6	/**
7	 * Canonical form for an owner address, applied whenever an owner is created. The address is trimmed,
8	 * its internal whitespace collapsed to single spaces, upper-cased, and common abbreviations expanded
9	 * on a whole-word basis ({@code ST}&rarr;{@code STREET}, {@code RD}&rarr;{@code ROAD},
10	 * {@code AVE}&rarr;{@code AVENUE}). The result is idempotent, so normalizing an already-normalized
11	 * value leaves it unchanged.
12	 *
13	 * <p>Used both to store/return the address and for every address comparison (household duplicate
14	 * detection and the shared household id), so all addresses are judged in the same normalized form.
15	 */
16	public final class AddressNormalizer {
17	
18	    private static final Map<String, String> ABBREVIATIONS = Map.of(
19	            "ST", "STREET",
20	            "RD", "ROAD",
21	            "AVE", "AVENUE");
22	
23	    private AddressNormalizer() {
24	    }
25	
26	    /** Normalize an address; {@code null} becomes an empty string. */
27	    public static String normalize(String value) {
28	        if (value == null) {
29	            return "";
30	        }
31	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
32	        if (collapsed.isEmpty()) {
33	            return "";
34	        }
35	        String[] tokens = collapsed.split(" ");
36	        StringBuilder sb = new StringBuilder(collapsed.length());
37	        for (int i = 0; i < tokens.length; i++) {
38	            if (i > 0) {
39	                sb.append(' ');
40	            }
41	            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
42	        }
43	        return sb.toString();
44	    }
45	}
